[System.Serializable]
public struct MinMaxFloat
{
    public float min;
    public float max;

    public float RandomValue => UnityEngine.Random.Range(min, max);
    public bool IsInRange(float value) => value >= min && value <= max;
}

[CustomPropertyDrawer(typeof(MinMaxFloat))]
public class MinMaxFloatDrawer : PropertyDrawer
{
    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        EditorGUI.BeginProperty(position, label, property);
        SerializedProperty minProp = property.FindPropertyRelative("min");
        SerializedProperty maxProp = property.FindPropertyRelative("max");
        position = EditorGUI.PrefixLabel(position, GUIUtility.GetControlID(FocusType.Passive), label);
        float labelWidth = 30f;
        float fieldWidth = (position.width - labelWidth * 2) / 2f - 5f;
        Rect minLabelRect = new Rect(position.x, position.y, labelWidth, position.height);
        Rect minFieldRect = new Rect(position.x + labelWidth, position.y, fieldWidth, position.height);
        Rect maxLabelRect = new Rect(position.x + labelWidth + fieldWidth + 5f, position.y, labelWidth, position.height);
        Rect maxFieldRect = new Rect(position.x + labelWidth * 2 + fieldWidth + 5f, position.y, fieldWidth, position.height);
        EditorGUI.LabelField(minLabelRect, "Min");
