    // ============================================
    // OBJECT POOLING: THE MOST IMPORTANT OPTIMIZATION
    // ============================================

    [System.Serializable]
    public class ObjectPool<T> where T : Component
    {
        private T prefab;
        private Queue<T> pool;
        private Transform parent;
        private int initialSize;

        public ObjectPool(T prefab, int initialSize, Transform parent = null)
        {
            this.prefab = prefab;
            this.initialSize = initialSize;
            this.parent = parent;
            this.pool = new Queue<T>(initialSize);

            for (int i = 0; i < initialSize; i++)
            {
                T instance = Object.Instantiate(prefab, parent);
                instance.gameObject.SetActive(false);
                pool.Enqueue(instance);
            }
        }

        public T Get()
        {
            if (pool.Count > 0)
            {
                T instance = pool.Dequeue();
                instance.gameObject.SetActive(true);
                return instance;
            }

            Debug.LogWarning("Pool expanded at runtime. Consider increasing initial size.");
            T newInstance = Object.Instantiate(prefab, parent);
            return newInstance;
        }

        public void Return(T instance)
        {
            instance.gameObject.SetActive(false);
            pool.Enqueue(instance);
        }
    }

