using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;
using System.Collections.Generic;

public class AddressablesManager : MonoBehaviour
{
    public static AddressablesManager Instance { get; private set; }

    private Dictionary<string, AsyncOperationHandle> loadedAssets = new();
    private Dictionary<string, int> referenceCounts = new();

    void Awake()
    {
        if (Instance != null) { Destroy(gameObject); return; }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    public async System.Threading.Tasks.Task<T> LoadAssetAsync<T>(string key) where T : Object
    {
        if (loadedAssets.TryGetValue(key, out var existingHandle))
        {
            referenceCounts[key]++;
            return existingHandle.Result as T;
        }

        AsyncOperationHandle<T> handle = Addressables.LoadAssetAsync<T>(key);
        await handle.Task;

        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            loadedAssets[key] = handle;
            referenceCounts[key] = 1;
            return handle.Result;
        }
        else
        {
            Debug.LogError($"Failed to load asset: {key}");
            return null;
        }
    }

    public async System.Threading.Tasks.Task<GameObject> InstantiateAsync(
        string key, Vector3 position, Quaternion rotation, Transform parent = null)
    {
        AsyncOperationHandle<GameObject> handle = 
            Addressables.InstantiateAsync(key, position, rotation, parent);

        await handle.Task;

        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            string instanceKey = $"{key}_{handle.Result.GetInstanceID()}";
            loadedAssets[instanceKey] = handle;
            referenceCounts[instanceKey] = 1;
            return handle.Result;
        }

        return null;
    }

    public void ReleaseAsset(string key)
    {
        if (!referenceCounts.ContainsKey(key)) return;

        referenceCounts[key]--;

        if (referenceCounts[key] <= 0)
        {
            if (loadedAssets.TryGetValue(key, out var handle))
            {
                Addressables.Release(handle);
                loadedAssets.Remove(key);
                referenceCounts.Remove(key);
            }
        }
    }

    public async System.Threading.Tasks.Task LoadSceneAsync(string sceneKey, bool additive = false)
    {
        var handle = Addressables.LoadSceneAsync(sceneKey, 
            additive ? UnityEngine.SceneManagement.LoadSceneMode.Additive :
                        UnityEngine.SceneManagement.LoadSceneMode.Single);

        await handle.Task;

        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            Debug.Log($"Scene loaded: {sceneKey}");
        }
    }

    public async System.Threading.Tasks.Task PreloadLabel(string label)
    {
        var handle = Addressables.LoadAssetsAsync<Object>(label, null);
        await handle.Task;

        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            foreach (var asset in handle.Result)
            {
                Debug.Log($"Preloaded: {asset.name}");
            }
        }
    }

    void OnDestroy()
    {
        foreach (var handle in loadedAssets.Values)
        {
            if (handle.IsValid())
            {
                Addressables.Release(handle);
            }
        }
        loadedAssets.Clear();
        referenceCounts.Clear();
    }
}

