using UnityEngine;
using System;
using System.Diagnostics;

// ============================================
// DEFENSIVE NULL CHECKING WITH CONTEXT
// ============================================
public static class Assert
{
    [Conditional("UNITY_EDITOR")]
    public static void NotNull<T>(T obj, string context, UnityEngine.Object owner = null) where T : class
    {
        if (obj == null)
        {
            string message = $"[ASSERT FAIL] {context}: Expected {typeof(T).Name} to be non-null.";
            if (owner != null)
                message += $" On GameObject: {owner.name}";
            UnityEngine.Debug.LogError(message, owner);
        }
    }

    [Conditional("UNITY_EDITOR")]
    public static void IsTrue(bool condition, string message, UnityEngine.Object owner = null)
    {
        if (!condition)
            UnityEngine.Debug.LogError($"[ASSERT FAIL] {message}", owner);
    }

    [Conditional("UNITY_EDITOR")]
    public static void IsValidIndex(int index, int count, string arrayName, UnityEngine.Object owner = null)
    {
        if (index < 0 || index >= count)
            UnityEngine.Debug.LogError($"[ASSERT FAIL] Index {index} out of range [0, {count}) in {arrayName}", owner);
    }
}

// ============================================
// RESULT TYPE: EXPLICIT ERROR HANDLING
// ============================================
public readonly struct Result<T>
{
    public readonly bool IsSuccess;
    public readonly T Value;
    public readonly string Error;

    private Result(T value, bool success, string error)
    {
        Value = value;
        IsSuccess = success;
        Error = error;
    }

    public static Result<T> Success(T value) => new Result<T>(value, true, null);
    public static Result<T> Failure(string error) => new Result<T>(default, false, error);

    public T Unwrap()
    {
        if (!IsSuccess)
            throw new InvalidOperationException($"Cannot unwrap failed result: {Error}");
        return Value;
    }

    public T UnwrapOr(T defaultValue) => IsSuccess ? Value : defaultValue;

    public void Match(Action<T> onSuccess, Action<string> onFailure)
    {
        if (IsSuccess) onSuccess?.Invoke(Value);
        else onFailure?.Invoke(Error);
    }
}

// ============================================
// USAGE: EXPLICIT ERROR HANDLING
// ============================================
public class ProductionInventory : MonoBehaviour
{
    [SerializeField] private int capacity = 20;
    private ItemInstance[] items;
    private int count = 0;

    void Awake()
    {
        items = new ItemInstance[capacity];
    }

    public Result<int> AddItem(ItemInstance item)
    {
        if (item == null)
            return Result<int>.Failure("Cannot add null item");

        if (count >= capacity)
            return Result<int>.Failure("Inventory full");

        if (!item.IsStackable && HasItem(item.BaseData))
            return Result<int>.Failure($"Non-stackable item {item.BaseData.itemName} already exists");

        if (item.IsStackable)
        {
            for (int i = 0; i < count; i++)
            {
                if (items[i].BaseData == item.BaseData && items[i].StackCount < item.BaseData.maxStackSize)
                {
                    int space = item.BaseData.maxStackSize - items[i].StackCount;
                    int toAdd = Math.Min(space, item.StackCount);
                    items[i].StackCount += toAdd;
                    item.StackCount -= toAdd;

                    if (item.StackCount <= 0)
                        return Result<int>.Success(i);
                }
            }
        }

        if (count < capacity)
        {
            items[count] = item;
            count++;
            return Result<int>.Success(count - 1);
        }

        return Result<int>.Failure("Unexpected: no space found");
    }

    public Result<ItemInstance> RemoveItem(int slotIndex)
    {
        Assert.IsValidIndex(slotIndex, count, nameof(items), this);

        if (slotIndex < 0 || slotIndex >= count)
            return Result<ItemInstance>.Failure($"Invalid slot index: {slotIndex}");

        ItemInstance removed = items[slotIndex];

        for (int i = slotIndex; i < count - 1; i++)
            items[i] = items[i + 1];
        items[count - 1] = null;
        count--;

        return Result<ItemInstance>.Success(removed);
    }

    bool HasItem(ItemData data)
    {
        for (int i = 0; i < count; i++)
            if (items[i]?.BaseData == data) return true;
        return false;
    }
}

// ============================================
// INITIALIZATION SAFETY
// ============================================
public abstract class InitializableMonoBehaviour : MonoBehaviour
{
    private bool isInitialized = false;

    public void Initialize()
    {
        if (isInitialized)
        {
            UnityEngine.Debug.LogWarning($"{GetType().Name} already initialized!", this);
            return;
        }

        OnInitialize();
        isInitialized = true;
    }

    protected abstract void OnInitialize();
    public bool IsInitialized => isInitialized;
}

public class GameInitializer : MonoBehaviour
{
    [SerializeField] private InitializableMonoBehaviour[] systems;
    [SerializeField] private bool autoInitialize = true;
    [SerializeField] private float delayBetweenSystems = 0.1f;

    async void Start()
    {
        if (!autoInitialize) return;

        foreach (var system in systems)
        {
            if (system == null)
            {
                UnityEngine.Debug.LogError("Null reference in initialization order!");
                continue;
            }

            system.Initialize();

            if (delayBetweenSystems > 0)
                await System.Threading.Tasks.Task
                    .Delay(TimeSpan.FromSeconds(delayBetweenSystems));
        }

        UnityEngine.Debug.Log("All systems initialized successfully.");
    }
}

using UnityEngine;
using System.Threading.Tasks;
using System;

public class AsyncPatterns : MonoBehaviour
{
    public async Task<bool> LoadWithTimeout(Func<Task> operation, float timeoutSeconds)
    {
        var timeout = Task.Delay(TimeSpan.FromSeconds(timeoutSeconds));
        var operationTask = operation();
        var completed = await Task.WhenAny(operationTask, timeout);

        if (completed == timeout)
        {
            Debug.LogWarning("Operation timed out!");
            return false;
        }
        return true;
    }

    public async Task<T> InitializeWithRetry<T>(Func<Task<T>> operation, int maxRetries = 3)
    {
        for (int i = 0; i < maxRetries; i++)
        {
            try
            {
                return await operation();
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"Attempt {i + 1}/{maxRetries} failed: {ex.Message}");
                await Task.Delay(TimeSpan.FromSeconds(Mathf.Pow(2, i)));
            }
        }
        throw new Exception($"Failed after {maxRetries} attempts");
    }

    private System.Threading.CancellationTokenSource cts;

    async void Start()
    {
        cts = new System.Threading.CancellationTokenSource();
        try
        {
            await LongRunningOperation(cts.Token);
        }
        catch (OperationCanceledException)
        {
            Debug.Log("Operation was cancelled cleanly.");
        }
    }

    async Task LongRunningOperation(System.Threading.CancellationToken token)
    {
        for (int i = 0; i < 100; i++)
        {
            token.ThrowIfCancellationRequested();
            await Task.Yield();
        }
    }

    void OnDestroy()
    {
        cts?.Cancel();
        cts?.Dispose();
    }

    public async Task LoadSceneWithProgress(string sceneName, IProgress<float> progress)
    {
        var operation = UnityEngine.SceneManagement.SceneManager.LoadSceneAsync(sceneName);
        operation.allowSceneActivation = false;

        while (operation.progress < 0.9f)
        {
            progress?.Report(operation.progress / 0.9f);
            await Task.Yield();
        }

        progress?.Report(1f);
        await Task.Delay(500);
        operation.allowSceneActivation = true;
    }

    public async Task LoadMultipleAssets()
    {
        var task1 = AddressablesManager.Instance.LoadAssetAsync<WeaponData>("Weapon_Rifle");
        var task2 = AddressablesManager.Instance.LoadAssetAsync<WeaponData>("Weapon_Shotgun");
        var task3 = AddressablesManager.Instance.LoadAssetAsync<WeaponData>("Weapon_Sniper");

        await Task.WhenAll(task1, task2, task3);
        Debug.Log("All weapons loaded!");
    }
}

using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using System.Collections;

public class InventoryTests
{
    [Test]
    public void AddItem_ToEmptySlot_ReturnsSuccess()
    {
        var inventory = new InventorySystem(capacity: 10);
        var item = CreateTestItem("Sword", isStackable: false);

        var result = inventory.AddItem(item);

        Assert.IsTrue(result.IsSuccess);
        Assert.AreEqual(0, result.Value);
    }

    [Test]
    public void AddItem_ToFullInventory_ReturnsFailure()
    {
        var inventory = new InventorySystem(capacity: 1);
        inventory.AddItem(CreateTestItem("Item1"));

        var result = inventory.AddItem(CreateTestItem("Item2"));

        Assert.IsFalse(result.IsSuccess);
        Assert.AreEqual("Inventory full", result.Error);
    }

    [Test]
    public void StackItem_SameType_IncreasesStackCount()
    {
        var inventory = new InventorySystem(capacity: 10);
        var data = ScriptableObject.CreateInstance<ItemData>();
        data.maxStackSize = 5;

        var item1 = new ItemInstance(data) { StackCount = 3 };
        var item2 = new ItemInstance(data) { StackCount = 2 };

        inventory.AddItem(item1);
        var result = inventory.AddItem(item2);

        Assert.IsTrue(result.IsSuccess);
        Assert.AreEqual(5, inventory.GetItemAt(0).StackCount);
    }

    [Test]
    public void RemoveItem_InvalidIndex_ReturnsFailure()
    {
        var inventory = new InventorySystem(capacity: 10);

        var result = inventory.RemoveItem(5);

        Assert.IsFalse(result.IsSuccess);
        StringAssert.Contains("Invalid slot", result.Error);
    }

    private ItemInstance CreateTestItem(string name, bool isStackable = false)
    {
        var data = ScriptableObject.CreateInstance<ItemData>();
        data.itemName = name;
        data.isStackable = isStackable;
        data.maxStackSize = isStackable ? 10 : 1;
        return new ItemInstance(data);
    }
}

public class PlayerMovementTests
{
