    public IEnumerator Player_MovesForward_WhenWPressed()
    {
        var playerObj = new GameObject("Player");
        var player = playerObj.AddComponent<PlayerMovement>();
        player.moveSpeed = 5f;

        Vector3 startPos = playerObj.transform.position;
        playerObj.transform.position += Vector3.forward * player.moveSpeed * Time.deltaTime;

        yield return null;

        Assert.Greater(playerObj.transform.position.z, startPos.z);
        Object.Destroy(playerObj);
    }

