    public IEnumerator Player_Jumps_WhenSpacePressed()
    {
        var playerObj = new GameObject("Player");
        playerObj.AddComponent<Rigidbody>();
        var player = playerObj.AddComponent<PlayerMovement>();
        player.jumpForce = 10f;

        float startY = playerObj.transform.position.y;
        player.Jump();

        yield return new WaitForFixedUpdate();
        yield return new WaitForFixedUpdate();

        Assert.Greater(playerObj.transform.position.y, startY);
        Object.Destroy(playerObj);
    }
